    }

    private Interval evalBinop(Interval l, BinOp op, Interval r) {
        if (l.isBottom() || r.isBottom()) return Interval.EMPTY;
        if (l.min == null || l.max == null || r.min == null || r.max == null) return Interval.TOP;

        switch (op) {
            case Add:
