            return new Interval(constVal.v(), constVal.v());
        } else if (rval instanceof RVal.Binop binop) {
            Interval l = evalRVal(binop.l(), state);
            Interval r = evalRVal(binop.r(), state);
            return evalBinop(l, binop.op(), r);
        } else if (rval instanceof LVal local) {
            return state.get(lvalToString(local));
